//! OpenAPI adapter parity with upstream `@opencode/codemode` (`src/openapi/*`, `test/openapi.test.ts`).
//!
//! 1. Every recorded `OpenAPI.fromSpec` call (`openapi-fromspec.jsonl`) yields the same tool tree and skipped list.
//! 2. Every recorded HTTP round trip (`openapi-http.jsonl`) sends the same request and produces the same result.
//! 3. Every recorded execution using OpenAPI tools (`openapi.test.jsonl`) replays through `CodeMode` + `OpenApiHost`.
//! 4. Extra cases (`tests/fixtures/openapi/cases.json`, written by `cases.py`) with expectations generated by running
//!    upstream (`expected.json`: `bun run harness.ts cases.json` from inside upstream `packages/codemode`, with the
//!    `b3`/`traceparent` tracing headers Effect's client layer adds stripped from the recorded requests).

mod common;

use std::sync::{Arc, Mutex};

use common::*;
use futures::future::BoxFuture;
use oc_codemode::codemode::CodeMode;
use oc_codemode::host::{HttpClient, HttpRequest, HttpResponse, ToolCallError};
use oc_codemode::openapi::{
    ApiKeyLocation, AuthContext, AuthResolver, Credential, OpenApi, OpenApiHost, Options, SecurityScheme, from_spec,
};
use oc_codemode::tool_runtime::{ToolDef, ToolEntry, signature_of};
use oc_codemode::tool_schema::{ToolSchema, output_typescript, schema_to_typescript};
use serde_json::{Map, Value as Json, json};

const MIB_50: usize = 50 * 1024 * 1024;

fn records(name: &str) -> Vec<Json> {
    read_jsonl(&fixtures().join(name)).into_iter().map(|r| plain_instances(&r)).collect()
}

/// A recorded class instance (`{"$instance", "fields"}`, e.g. an object with a custom prototype) is, for a Rust host,
/// just its own fields.
fn plain_instances(value: &Json) -> Json {
    match value {
        Json::Object(m) if m.len() == 2 && m.contains_key("$instance") && m.contains_key("fields") => {
            plain_instances(&m["fields"])
        }
        Json::Object(m) => Json::Object(m.iter().map(|(k, v)| (k.clone(), plain_instances(v))).collect()),
        Json::Array(items) => Json::Array(items.iter().map(plain_instances).collect()),
        other => other.clone(),
    }
}

fn local_fixture(name: &str) -> Json {
    let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/openapi").join(name);
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

// ---------------------------------------------------------------------------------------------------------------
// Auth resolvers

type Contexts = Arc<Mutex<Vec<AuthContext>>>;

fn resolver(
    f: impl Fn(&AuthContext) -> Result<Option<Credential>, String> + Send + Sync + 'static,
    contexts: Contexts,
) -> Arc<dyn AuthResolver> {
    Arc::new(move |context: AuthContext| -> BoxFuture<'static, Result<Option<Credential>, String>> {
        let result = f(&context);
        contexts.lock().unwrap().push(context);
        Box::pin(async move { result })
    })
}

fn bearer(token: &str) -> Credential {
    Credential::Bearer { token: token.into() }
}

fn api_key(value: &str) -> Credential {
    Credential::ApiKey { value: value.into() }
}

/// The resolvers the upstream tests pass (recorded only as `{"$function": "resolve"}`), keyed by test name.
fn fixture_resolver(test: &str, contexts: Contexts) -> Arc<dyn AuthResolver> {
    if test.contains("covers a representative API") {
        return resolver(
            |c| Ok(Some(if c.name == "BearerAuth" { bearer("bearer-secret") } else { api_key("api-secret") })),
            contexts,
        );
    }
    if test.contains("applies authentication carriers") {
        return resolver(
            |c| {
                Ok(match c.name.as_str() {
                    "bearer" => Some(bearer("secret")),
                    "cookie" => None,
                    _ => Some(api_key("secret")),
                })
            },
            contexts,
        );
    }
    resolver(|_| Ok(Some(bearer("secret"))), contexts)
}

fn fixture_options(record: &Json, contexts: Contexts) -> Options {
    let spec = decode(&record["spec"]).unwrap_or(Json::Null);
    let options = &record["options"];
    let mut out = Options::new(spec);
    out.base_url = options.get("baseUrl").and_then(|v| v.as_str()).map(String::from);
    if let Some(Json::Object(headers)) = options.get("headers") {
        out.headers = headers.iter().map(|(k, v)| (k.clone(), v.as_str().unwrap_or("").to_string())).collect();
    }
    if options.get("auth").is_some() {
        out.auth = Some(fixture_resolver(record["test"].as_str().unwrap_or(""), contexts));
    }
    out
}

// ---------------------------------------------------------------------------------------------------------------
// Tool trees

fn schema_record(schema: &ToolSchema) -> Json {
    match schema {
        ToolSchema::Json(s) => json!({"kind": "json", "schema": s}),
        other => panic!("unexpected schema {other:?}"),
    }
}

/// The recorder's trie format for a list of tools.
fn trie(entries: &[ToolEntry]) -> Json {
    #[derive(Default)]
    struct Node {
        tool: Option<Json>,
        children: Vec<(String, Node)>,
    }
    let mut root = Node::default();
    for entry in entries {
        let ToolEntry::Tool(def) = entry else { panic!("namespace entries are not generated") };
        let mut node = &mut root;
        for segment in def.path.split('.') {
            let index = match node.children.iter().position(|(n, _)| n == segment) {
                Some(i) => i,
                None => {
                    node.children.push((segment.to_string(), Node::default()));
                    node.children.len() - 1
                }
            };
            node = &mut node.children[index].1;
        }
        node.tool = Some(json!({
            "description": def.description,
            "input": schema_record(&def.input),
            "output": def.output.as_ref().map(schema_record).unwrap_or(Json::Null),
        }));
    }
    fn render(node: &Node) -> Json {
        let mut out = Map::new();
        out.insert("children".into(), Json::Array(node.children.iter().map(|(n, c)| json!([n, render(c)])).collect()));
        if let Some(tool) = &node.tool {
            out.insert("tool".into(), tool.clone());
        }
        Json::Object(out)
    }
    render(&root)
}

fn skipped_json(api: &OpenApi) -> Json {
    Json::Array(api.skipped.iter().map(|s| json!({"method": s.method, "path": s.path, "reason": s.reason})).collect())
}

#[test]
fn from_spec_records_match_upstream() {
    let all = records("openapi-fromspec.jsonl");
    assert!(all.len() >= 40);
    let mut failures = Vec::new();
    for (i, record) in all.iter().enumerate() {
        let test = record["test"].as_str().unwrap_or("");
        let result = from_spec(fixture_options(record, Arc::default()));
        if let Some(throws) = record.get("throws") {
            match result {
                Err(e) if e.message == throws["message"] => {}
                other => failures.push(format!("#{i} {test}: expected throw {throws}, got {other:?}")),
            }
            continue;
        }
        let api = match result {
            Ok(api) => api,
            Err(e) => {
                failures.push(format!("#{i} {test}: threw {e:?}"));
                continue;
            }
        };
        let tree = trie(&api.tools);
        let expected_tree = decode(&record["tree"]).unwrap();
        if !json_eq(&tree, &expected_tree) {
            failures.push(format!("#{i} {test}: tree\n  expected {expected_tree}\n       got {tree}"));
        }
        let skipped = skipped_json(&api);
        if !json_eq(&skipped, &record["skipped"]) {
            failures.push(format!("#{i} {test}: skipped\n  expected {}\n       got {skipped}", record["skipped"]));
        }
        // Rendering must not fail (the diamond-shaped reference graph renders exponentially, as upstream).
        if !test.contains("diamond") {
            for entry in &api.tools {
                if let ToolEntry::Tool(def) = entry {
                    let _ = signature_of(def);
                }
            }
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}

/// Assertions ported from `test/openapi.test.ts` (`inputTypeScript` / `outputTypeScript`), over the recorded specs.
#[test]
fn ported_signature_assertions() {
    let all = records("openapi-fromspec.jsonl");
    let api_for = |test: &str, nth: usize| {
        let record = all.iter().filter(|r| r["test"].as_str().is_some_and(|t| t.ends_with(test))).nth(nth).unwrap();
        from_spec(fixture_options(record, Arc::default())).unwrap()
    };
    let tool = |api: &OpenApi, path: &str| -> ToolDef {
        api.tools
            .iter()
            .find_map(|e| match e {
                ToolEntry::Tool(d) if d.path == path => Some(d.clone()),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{path} not generated"))
    };
    let input_ts = |d: &ToolDef| schema_to_typescript(&d.input, false);
    let output_ts = |d: &ToolDef| output_typescript(d.output.as_ref(), false);

    let api = api_for("covers a representative API from generation through execution", 0);
    assert_eq!(
        input_ts(&tool(&api, "users.get")),
        r#"{ userId: string; include?: Array<string>; verbose?: boolean; "X-Trace-ID"?: string }"#
    );
    assert_eq!(input_ts(&tool(&api, "users.create")), r#"{ name: string; email: string; role?: "admin" | "member" }"#);
    assert_eq!(
        input_ts(&tool(&api, "search.run")),
        "{ filter?: { query: string; page?: number }; tags?: Array<string> }"
    );
    assert_eq!(input_ts(&tool(&api, "users.remove")), "{ userId: string }");
    assert!(output_ts(&tool(&api, "users.get")).contains("id: string"));
    assert!(output_ts(&tool(&api, "users.create")).contains(r#"role?: "admin" | "member""#));
    assert_eq!(output_ts(&tool(&api, "search.run")), "string");
    assert_eq!(output_ts(&tool(&api, "users.remove")), "null");

    let api = api_for("generates supported operations and reports unsupported transports", 0);
    assert_eq!(input_ts(&tool(&api, "records.get")), "{ recordID: string }");
    assert_eq!(output_ts(&tool(&api, "records.get")), "{ id: string; value: string }");

    let api = api_for("preserves operation path sanitization and collision handling", 0);
    for path in ["group.item", "group_item_2", "group.operation.other"] {
        tool(&api, path);
    }
    let api = api_for("synthesizes flat operation IDs from methods and paths", 0);
    for path in [
        "getUsers",
        "postUsers",
        "getUsersById",
        "patchUsersById",
        "deleteUsersById",
        "getOrganizationsByOrganizationidUsersById",
    ] {
        tool(&api, path);
    }
    assert_eq!(
        input_ts(&tool(&api_for("lets operation parameters override matching path parameters", 0), "test")),
        "{ limit: number }"
    );
    let search = tool(&api_for("normalizes OpenAPI 3.0 schemas with Effect", 0), "search");
    assert_eq!(input_ts(&search), "{ value?: string | null }");
    let ToolSchema::Json(input) = &search.input else { unreachable!() };
    assert_eq!(input["properties"]["value"]["minLength"], json!(2));
    for nth in 0..2 {
        let create =
            tool(&api_for("projects read-only and write-only properties by schema direction", nth), "users.create");
        assert_eq!(input_ts(&create), "{ name: string; password: string; profile: { secret: string; label: string } }");
        assert_eq!(
            output_ts(&create),
            "{ id: string; name: string; profile: { createdAt: string; label: string }; generated: string }"
        );
    }
    for (test, expected) in [
        ("projects directional annotations through local refs and allOf composition", "{ name: string }"),
        ("honors directional declarations on intermediate reference hops", "{ name: string }"),
        ("projects directional annotations inside parameter schemas", "{ filter: { state: string } }"),
        ("resolves bearer authentication without exposing it as input", "{}"),
    ] {
        let api = api_for(test, 0);
        let path = if test.starts_with("resolves bearer") { "getTest" } else { "test" };
        assert_eq!(input_ts(&tool(&api, path)), expected, "{test}");
    }
    for nth in 0..2 {
        assert_eq!(
            input_ts(&tool(
                &api_for("resolves hiding through reference cycles regardless of evaluation order", nth),
                "test"
            )),
            "{ name: string }"
        );
    }
    assert_eq!(
        output_ts(&tool(&api_for("keeps non-JSON responses raw and unions every success output", 0), "test")),
        "string | null"
    );
    let api = api_for("prefixes cross-location collisions and reconstructs the HTTP request", 0);
    assert_eq!(
        input_ts(&tool(&api, "things.update")),
        "{ path_id: string; query_id: string; path_id_2?: string; header_id: string; body_id: string }"
    );
    assert_eq!(input_ts(&tool(&api, "echo")), "{ body: string }");
    assert_eq!(
        input_ts(&tool(
            &api_for("keeps bodies nested when flattening would lose schema semantics", 0),
            "body.optional"
        )),
        "{ body?: { name: string } }"
    );
}

// ---------------------------------------------------------------------------------------------------------------
// HTTP

/// A client returning canned responses and recording what it was sent.
type Responder = Box<dyn Fn(&HttpRequest) -> Result<HttpResponse, String> + Send + Sync>;

struct MockClient {
    respond: Responder,
    requests: Mutex<Vec<HttpRequest>>,
}

impl MockClient {
    fn new(respond: impl Fn(&HttpRequest) -> Result<HttpResponse, String> + Send + Sync + 'static) -> Arc<MockClient> {
        Arc::new(MockClient { respond: Box::new(respond), requests: Mutex::new(Vec::new()) })
    }
}

impl HttpClient for MockClient {
    fn send(&self, request: HttpRequest) -> BoxFuture<'static, Result<HttpResponse, String>> {
        let response = (self.respond)(&request);
        self.requests.lock().unwrap().push(request);
        Box::pin(async move { response })
    }
}

fn response(status: u16, headers: Vec<(String, String)>, body: Vec<u8>) -> HttpResponse {
    HttpResponse { url: String::new(), status, status_text: String::new(), redirected: false, headers, body }
}

/// A recorded `{status, headers, body?}` response. A response the recorder saw no body for while the call failed
/// with an oversize error was a 50 MiB + 1 stream.
fn recorded_response(record: &Json, oversized: bool) -> HttpResponse {
    let headers: Vec<(String, String)> = record["headers"]
        .as_object()
        .map(|h| h.iter().map(|(k, v)| (k.to_lowercase(), v.as_str().unwrap_or("").to_string())).collect())
        .unwrap_or_default();
    let body = match record.get("body").and_then(|b| b.as_str()) {
        Some(text) => text.as_bytes().to_vec(),
        None if oversized && !headers.iter().any(|(k, _)| k == "content-length") => vec![0; MIB_50 + 1],
        None => Vec::new(),
    };
    response(record["status"].as_u64().unwrap_or(200) as u16, headers, body)
}

fn request_json(request: &HttpRequest) -> Json {
    json!({
        "method": request.method,
        "url": request.url,
        "headers": Json::Object(request.headers.iter().map(|(k, v)| (k.clone(), Json::String(v.clone()))).collect()),
        "body": request.body.as_ref().map(|b| Json::String(String::from_utf8_lossy(b).into_owned())).unwrap_or(Json::Null),
    })
}

/// The recorder's request (`{method, url, headers, body: {tag, text?}}`) in `request_json` form.
fn recorded_request(record: &Json) -> Json {
    json!({
        "method": record["method"],
        "url": record["url"],
        "headers": record["headers"],
        "body": if record["body"]["tag"] == "Uint8Array" { record["body"]["text"].clone() } else { Json::Null },
    })
}

fn outcome_json(result: &Result<Option<Json>, ToolCallError>) -> Json {
    match result {
        Ok(value) => json!({"value": value.clone().unwrap_or(json!({"$undefined": true}))}),
        Err(ToolCallError::Failure(message)) => json!({"error": message}),
        Err(ToolCallError::InvalidOutput(message)) => json!({"invalidOutput": message}),
    }
}

fn contains_marker(value: &Json, marker: &str) -> bool {
    match value {
        Json::Object(m) => m.contains_key(marker) || m.values().any(|v| contains_marker(v, marker)),
        Json::Array(items) => items.iter().any(|v| contains_marker(v, marker)),
        _ => false,
    }
}

fn operation_json(api: &OpenApi, path: &str) -> Json {
    let op = &api.plan(path).unwrap().operation;
    json!({
        "operationId": op.operation_id,
        "method": op.method,
        "path": op.path,
        "summary": op.summary,
        "description": op.description,
    })
}

/// The tool of `api` whose plan is the one recorded (same operation and URL).
fn tool_for(api: &OpenApi, record: &Json) -> Option<String> {
    let expected = decode(&record["operation"]).unwrap();
    api.plans().iter().find_map(|(path, plan)| {
        let ours = operation_json(api, path);
        let ours = decode(&json!(ours)).unwrap();
        let same = ours["method"] == expected["method"]
            && ours["path"] == expected["path"]
            && ours["operationId"] == expected.get("operationId").cloned().unwrap_or(Json::Null)
            && ours["summary"] == expected.get("summary").cloned().unwrap_or(Json::Null)
            && ours["description"] == expected.get("description").cloned().unwrap_or(Json::Null)
            && plan.url == record["planUrl"].as_str().unwrap_or("");
        same.then(|| path.clone())
    })
}

async fn replay_http(api: &OpenApi, path: &str, record: &Json) -> Result<(), String> {
    let failed = record["outcome"] == "failure";
    let oversized = failed && record["error"].as_str().is_some_and(|e| e.contains("exceeds 50 MiB"));
    let canned =
        if record["response"].is_null() { None } else { Some(recorded_response(&record["response"], oversized)) };
    let client = MockClient::new(move |_| canned.clone().ok_or_else(|| "unexpected request".to_string()));
    let input = decode(&record["input"]);
    let result = api.call(client.clone(), path, input).await;
    let sent: Vec<Json> = client.requests.lock().unwrap().iter().map(request_json).collect();
    let expected_sent: Vec<Json> =
        if record["request"].is_null() { Vec::new() } else { vec![recorded_request(&record["request"])] };
    if !json_eq(&Json::Array(sent.clone()), &Json::Array(expected_sent.clone())) {
        return Err(format!("request\n  expected {expected_sent:?}\n       got {sent:?}"));
    }
    let expected = if failed { json!({"error": record["error"]}) } else { json!({"value": record["value"]}) };
    let ours = outcome_json(&result);
    if json_eq(&decode(&ours).unwrap(), &decode(&expected).unwrap()) {
        Ok(())
    } else {
        Err(format!("outcome\n  expected {expected}\n       got {ours}"))
    }
}

/// Recorded inputs Rust hosts cannot produce: tool input is JSON, so it holds neither `undefined` nor cycles.
fn unrepresentable_input(record: &Json) -> Option<&'static str> {
    if contains_marker(&record["input"], "$undefined") {
        Some("input contains undefined")
    } else if contains_marker(&record["input"], "$circular") {
        Some("input is cyclic")
    } else {
        None
    }
}

#[tokio::test]
async fn http_round_trips_match_upstream() {
    let specs = records("openapi-fromspec.jsonl");
    let all = records("openapi-http.jsonl");
    assert!(all.len() >= 20);
    let mut failures = Vec::new();
    let mut replayed = 0;
    for (i, record) in all.iter().enumerate() {
        if unrepresentable_input(record).is_some() {
            continue;
        }
        let test = record["test"].as_str().unwrap_or("");
        let mut ok = false;
        let mut attempts = Vec::new();
        for spec in specs.iter().filter(|s| s["test"] == record["test"] && s.get("throws").is_none()) {
            let api = from_spec(fixture_options(spec, Arc::default())).unwrap();
            let Some(path) = tool_for(&api, record) else { continue };
            match replay_http(&api, &path, record).await {
                Ok(()) => {
                    ok = true;
                    break;
                }
                Err(e) => attempts.push(e),
            }
        }
        if ok {
            replayed += 1;
        } else if attempts.is_empty() {
            failures.push(format!("#{i} {test}: no generated tool matches the recorded operation"));
        } else {
            failures.push(format!("#{i} {test}: {}", attempts.join("\n   or ")));
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
    assert!(replayed >= 20, "replayed {replayed}");
}

#[tokio::test]
async fn representative_api_resolves_auth_in_order() {
    let spec = records("openapi-fromspec.jsonl").into_iter().next().unwrap();
    let contexts: Contexts = Arc::default();
    let api = from_spec(fixture_options(&spec, contexts.clone())).unwrap();
    let client = MockClient::new(|_| {
        Ok(response(200, vec![("content-type".into(), "application/json".into())], b"{}".to_vec()))
    });
    for (path, input) in [
        ("users.get", json!({"userId": "u"})),
        ("users.create", json!({"name": "n", "email": "e"})),
        ("search.run", json!({})),
        ("users.remove", json!({"userId": "u"})),
    ] {
        api.call(client.clone(), path, Some(input)).await.unwrap();
    }
    let names: Vec<String> = contexts.lock().unwrap().iter().map(|c| c.name.clone()).collect();
    assert_eq!(names, ["BearerAuth", "ApiKey", "BearerAuth"]);
}

#[tokio::test]
async fn bearer_resolution_context() {
    let record = records("openapi-fromspec.jsonl")
        .into_iter()
        .find(|r| r["test"].as_str().unwrap().ends_with("resolves bearer authentication without exposing it as input"))
        .unwrap();
    let contexts: Contexts = Arc::default();
    let api = from_spec(fixture_options(&record, contexts.clone())).unwrap();
    let client = MockClient::new(|_| Ok(response(200, vec![], Vec::new())));
    api.call(client, "getTest", Some(json!({}))).await.unwrap();
    let contexts = contexts.lock().unwrap();
    assert_eq!(contexts.len(), 1);
    assert_eq!(contexts[0].name, "bearer");
    assert_eq!(contexts[0].definition, SecurityScheme::Http { scheme: "bearer".into() });
    assert!(contexts[0].scopes.is_empty());
    let op = &contexts[0].operation;
    assert_eq!((op.operation_id.as_deref(), op.method.as_str(), op.path.as_str()), (None, "GET", "/test"));
    assert_eq!((op.summary.as_deref(), op.description.as_deref()), (None, None));
}

#[tokio::test]
async fn invalid_urls_are_transport_failures() {
    // Upstream (FetchHttpClient): `ToolError: GET :99999/x failed: transport error (cause: HttpClientError: InvalidUrl
    // error (GET http://localhost:99999/x) (cause: UrlError (cause: TypeError: "http://localhost:99999/x" cannot be
    // parsed as a URL.)))`.
    let spec = json!({"openapi": "3.1.0", "paths": {":99999/x": {"get": {"operationId": "test", "responses": {"200": {"description": "ok"}}}}}});
    let api = from_spec(Options::new(spec).base_url("http://localhost")).unwrap();
    let client = MockClient::new(|_| Err("unreachable".into()));
    let result = api.call(client.clone(), "test", Some(json!({}))).await;
    assert_eq!(
        result,
        Err(ToolCallError::Failure("ToolError: GET :99999/x failed: transport error (cause: HttpClientError: InvalidUrl error (GET http://localhost:99999/x) (cause: UrlError (cause: TypeError: \"http://localhost:99999/x\" cannot be parsed as a URL.)))".into()))
    );
    assert!(client.requests.lock().unwrap().is_empty());
}

#[tokio::test]
async fn transport_errors_are_tool_failures() {
    // Upstream (FetchHttpClient, connection refused): `ToolError: POST /test failed: transport error (cause:
    // HttpClientError: Transport error (POST http://127.0.0.1:1/test) (cause: Error: Unable to connect. Is the
    // computer able to access the url?))`; the innermost message is whatever the host client reports.
    let spec = json!({"openapi": "3.1.0", "paths": {"/x": {"get": {"operationId": "x", "parameters": [{"name": "q", "in": "query", "schema": {}}]}}}});
    let api = from_spec(Options::new(spec).base_url("http://localhost:4096/")).unwrap();
    let client = MockClient::new(|_| Err("Unable to connect.".into()));
    let result = api.call(client, "x", Some(json!({"q": 1}))).await;
    assert_eq!(
        result,
        Err(ToolCallError::Failure("ToolError: GET /x failed: transport error (cause: HttpClientError: Transport error (GET http://localhost:4096/x) (cause: Error: Unable to connect.))".into()))
    );
}

// ---------------------------------------------------------------------------------------------------------------
// Executions through CodeMode

/// Answers each request with the recorded response of an identical recorded request (same test).
fn replay_client(http: Vec<Json>) -> Arc<MockClient> {
    let used = Mutex::new(vec![false; http.len()]);
    MockClient::new(move |request| {
        let observed = request_json(request);
        let mut used = used.lock().unwrap();
        for (i, record) in http.iter().enumerate() {
            if !used[i] && !record["request"].is_null() && json_eq(&recorded_request(&record["request"]), &observed) {
                used[i] = true;
                return Ok(recorded_response(&record["response"], false));
            }
        }
        Err(format!("no recorded response for {observed}"))
    })
}

fn tree_tools(tree: &Json, path: &mut Vec<String>, out: &mut Vec<(String, Json)>) {
    if let Some(tool) = tree.get("tool") {
        out.push((path.join("."), tool.clone()));
    }
    for child in tree["children"].as_array().into_iter().flatten() {
        path.push(child[0].as_str().unwrap().to_string());
        tree_tools(&child[1], path, out);
        path.pop();
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn executions_replay_through_codemode() {
    let specs = records("openapi-fromspec.jsonl");
    let http = records("openapi-http.jsonl");
    let executions = records("openapi.test.jsonl");
    assert!(!executions.is_empty());
    let mut failures = Vec::new();
    for record in &executions {
        let test = record["test"].as_str().unwrap_or("");
        let spec = specs.iter().find(|s| s["test"] == record["test"]).expect("fromSpec record");
        let api = Arc::new(from_spec(fixture_options(spec, Arc::default())).unwrap());
        let mut recorded = Vec::new();
        tree_tools(&record["tree"], &mut Vec::new(), &mut recorded);
        let prefixed = api.tools.iter().all(|e| match e {
            ToolEntry::Tool(d) => recorded.iter().any(|(p, _)| *p == format!("api.{}", d.path)),
            _ => true,
        });
        let client = replay_client(http.iter().filter(|h| h["test"] == record["test"]).cloned().collect());
        let mut host = OpenApiHost::new(api.clone(), client);
        if prefixed {
            host = host.with_prefix("api");
        }
        let tools = host.tools();
        for (path, tool) in &recorded {
            let Some(def) = tools.iter().find_map(|e| match e {
                ToolEntry::Tool(d) if d.path == *path => Some(d),
                _ => None,
            }) else {
                failures.push(format!("{test}: missing tool {path}"));
                continue;
            };
            let checks = [
                ("signature", signature_of(def)),
                ("inputTs", schema_to_typescript(&def.input, false)),
                ("outputTs", output_typescript(def.output.as_ref(), false)),
            ];
            for (field, ours) in checks {
                if tool[field].as_str() != Some(ours.as_str()) {
                    failures.push(format!("{test}: {path} {field}\n  expected {}\n       got {ours}", tool[field]));
                }
            }
        }
        let runtime = CodeMode::new(tools, Arc::new(host), Vec::new(), limits_of(record)).unwrap();
        let ours = runtime.execute(record["code"].as_str().unwrap()).await.to_json();
        let expected = decode(&record["result"]).unwrap();
        if !json_eq(&ours, &expected) {
            failures.push(format!("{test}: result\n  expected {expected}\n       got {ours}"));
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}

