// Extra upstream cases

fn case_resolver(mode: Json, contexts: Contexts) -> Arc<dyn AuthResolver> {
    resolver(
        move |c| {
            let mode = match &mode {
                Json::String(s) => s.clone(),
                other => other[c.name.as_str()].as_str().unwrap_or("").to_string(),
            };
            Ok(Some(match mode.as_str() {
                "bearer" => bearer("tok"),
                "basic" => Credential::Basic { username: "Ada".into(), password: "pässword".into() },
                "header" => Credential::Header { name: "X-Custom".into(), value: "v".into() },
                "apikey" => api_key("key"),
                "fail" => return Err("vault locked".into()),
                _ => return Ok(None),
            }))
        },
        contexts,
    )
}

fn scheme_json(scheme: &SecurityScheme) -> Json {
    match scheme {
        SecurityScheme::ApiKey { name, location } => json!({"type": "apiKey", "name": name, "in": match location {
            ApiKeyLocation::Header => "header",
            ApiKeyLocation::Query => "query",
            ApiKeyLocation::Cookie => "cookie",
        }}),
        SecurityScheme::Http { scheme } => json!({"type": "http", "scheme": scheme}),
        SecurityScheme::OAuth2 => json!({"type": "oauth2"}),
        SecurityScheme::OpenIdConnect => json!({"type": "openIdConnect"}),
    }
}

fn tool_listing(api: &OpenApi) -> Json {
    let mut tools = Vec::new();
    let mut recorded = Vec::new();
    tree_tools(&trie(&api.tools), &mut Vec::new(), &mut recorded);
    for (path, _) in recorded {
        let def = api
            .tools
            .iter()
            .find_map(|e| match e {
                ToolEntry::Tool(d) if d.path == path => Some(d),
                _ => None,
            })
            .unwrap();
        let ToolSchema::Json(input) = &def.input else { unreachable!() };
        let output = match &def.output {
            Some(ToolSchema::Json(o)) => o.clone(),
            _ => Json::Null,
        };
        tools.push(json!({
            "path": def.path,
            "description": def.description,
            "input": input,
            "output": output,
            "inputTs": schema_to_typescript(&def.input, false),
            "outputTs": output_typescript(def.output.as_ref(), false),
        }));
    }
    Json::Array(tools)
}

#[tokio::test]
async fn extra_cases_match_upstream() {
    let cases = local_fixture("cases.json");
    let expected = local_fixture("expected.json");
    let cases = cases.as_array().unwrap();
    assert_eq!(cases.len(), expected.as_array().unwrap().len());
    let mut failures = Vec::new();
    for (case, expected) in cases.iter().zip(expected.as_array().unwrap()) {
        let name = case["name"].as_str().unwrap();
        let contexts: Contexts = Arc::default();
        let mut options = Options::new(case["spec"].clone());
        options.base_url = case.get("baseUrl").and_then(|v| v.as_str()).map(String::from);
        if let Some(Json::Object(headers)) = case.get("headers") {
            options.headers = headers.iter().map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string())).collect();
        }
        if let Some(mode) = case.get("auth") {
            options.auth = Some(case_resolver(mode.clone(), contexts.clone()));
        }
        let api = match from_spec(options) {
            Ok(api) => api,
            Err(e) => {
                let ours = json!({"throws": {"name": e.name, "message": e.message}});
                if !json_eq(&ours, expected) {
                    failures.push(format!("{name}\n  expected {expected}\n       got {ours}"));
                }
                continue;
            }
        };
        let Some(path) = case["tool"].as_str() else {
            let ours = json!({"skipped": skipped_json(&api), "tools": tool_listing(&api)});
            if !json_eq(&ours, expected) {
                failures.push(format!("{name}\n  expected {expected}\n       got {ours}"));
            }
            continue;
        };
        let Some(def) = api.tools.iter().find_map(|e| match e {
            ToolEntry::Tool(d) if d.path == path => Some(d.clone()),
            _ => None,
        }) else {
            let ours = json!({"missing": true, "skipped": skipped_json(&api)});
            if !json_eq(&ours, expected) {
                failures.push(format!("{name}\n  expected {expected}\n       got {ours}"));
            }
            continue;
        };
        let canned = &case["response"];
        let canned = response(
            canned["status"].as_u64().unwrap_or(200) as u16,
            canned["headers"]
                .as_object()
                .map(|h| h.iter().map(|(k, v)| (k.to_lowercase(), v.as_str().unwrap().to_string())).collect())
                .unwrap_or_default(),
            canned["body"].as_str().map(|b| b.as_bytes().to_vec()).unwrap_or_default(),
        );
        let client = MockClient::new(move |_| Ok(canned.clone()));
        let result = api.call(client.clone(), path, Some(case["input"].clone())).await;
        let mut ours = Map::new();
        ours.insert("requests".into(), Json::Array(client.requests.lock().unwrap().iter().map(request_json).collect()));
        ours.insert(
            "contexts".into(),
            Json::Array(
                contexts
                    .lock()
                    .unwrap()
                    .iter()
                    .map(|c| json!({"name": c.name, "definition": scheme_json(&c.definition), "scopes": c.scopes}))
                    .collect(),
            ),
        );
        ours.insert("inputTs".into(), Json::String(schema_to_typescript(&def.input, false)));
        ours.insert("outputTs".into(), Json::String(output_typescript(def.output.as_ref(), false)));
        for (k, v) in outcome_json(&result).as_object().unwrap() {
            ours.insert(k.clone(), v.clone());
        }
        let ours = Json::Object(ours);
        if !json_eq(&ours, expected) {
            failures.push(format!("{name}\n  expected {expected}\n       got {ours}"));
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn deep_documents_fail_like_a_stack_overflow() {
    // Built by hand: `json!` would re-serialize the nested value on every level.
    let mut schema = json!({"type": "string"});
    for _ in 0..10_001 {
        let mut map = Map::new();
        map.insert("items".into(), schema);
        schema = Json::Object(map);
    }
    let mut spec = json!({"openapi": "3.1.0", "components": {"schemas": {}}});
    spec["components"]["schemas"].as_object_mut().unwrap().insert("Deep".into(), schema);
    let err = from_spec(Options::new(spec).base_url("http://localhost")).unwrap_err();
    assert_eq!((err.name.as_str(), err.message.as_str()), ("RangeError", "Maximum call stack size exceeded."));
}
